const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];

const quotePremium = (step: QuoteStep): number => {
  const policyBasePremium = step.items.reduce(
    (sum, item) => sum + basePremiumOf(item),
    0,
  );
  return Math.ceil(
    addPercent(policyBasePremium, FIRST_INSURANCE_PERCENT) + PROCESSING_FEE,
  );
};
